use super::*;
use super::super::RetainedHistoryOriginPartial;
use semio_framework_value::{ErasedSnapshotRetirement,admit_owned_retirement,owned_retirement_birth_bytes};
use semio_framework_value::native_decoding::{NativeDecodeRetirementRecipient,NativeDecodeAllocation,NativeDecodeAllocationPort,NativeDecodeProgress};
fn observe<T>(action:impl FnOnce()->T)->(T,usize,usize){crate::test_allocation::observe_backing(action)}
fn receipt(owner:&mut RetainedHistoryOriginJsonDecode,g:RetainedCloneGrant,born:usize,released:usize){let(issued,p)=owner.take_receipt().unwrap();assert_eq!(issued,g);assert!(p.fits(g));assert_eq!((born,released),(p.retained_capacity_bytes,p.released_bytes))}
fn close_box<T:semio_framework_value::retirement::RetireOwned>(original:T,control:&mut NativeDecodeControl<'_>,g:RetainedCloneGrant)->(usize,usize){
 let capacity=owned_retirement_birth_bytes::<T>();assert!(capacity<=g.maximum_capacity_bytes);control.charge(capacity).unwrap();let(result,born,released)=observe(||admit_owned_retirement(original,g));let(child,p)=result.map_err(|(error,_)|error).unwrap();assert_eq!((born,released),(p.retained_capacity_bytes,p.released_bytes));
 let mut partial=RetainedHistoryOriginPartial::empty(DslValue::Null);partial.cells[0]=None;*partial.retiring=Some(child);let(mut births,mut releases)=(born,released);
 for _ in 0..100000{if partial.terminal_is_empty(){return(births,releases)}let demand=partial.close_demands(g.maximum_copy_bytes).unwrap();control.charge(demand.capacity_bytes).unwrap();let(progress,born,released)=observe(||partial.close_step(g).unwrap());assert!(progress.fits(g));assert_eq!((born,released),(progress.retained_capacity_bytes,progress.released_bytes));births+=born;releases+=released}panic!("original JSON receiving retirement did not terminate")
}
#[test]
fn original_history_origin_json_native_borrows_funded_grammar_and_same_original_control(){
 let policy:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let origins:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🔣️.json")).unwrap();let p=&policy["grant"];let n=|k:&str|p[k].as_u64().unwrap()as usize;let g=RetainedCloneGrant{maximum_items:n("items"),maximum_copy_bytes:n("copyBytes"),maximum_capacity_bytes:n("capacityBytes"),maximum_release_bytes:n("releaseBytes"),maximum_depth:n("depth")};let l=&policy["limits"];let limits=JsonReadLimits{maximum_bytes:l["bytes"].as_u64().unwrap(),maximum_allocation_bytes:l["allocationBytes"].as_u64().unwrap()as usize,maximum_depth:l["depth"].as_u64().unwrap()as usize,maximum_items:l["items"].as_u64().unwrap()};
 for row in origins["origins"].as_array().unwrap(){for cancelled in[0,1,7,50,300,100000]{
  let source=row["json"].as_str().unwrap().as_bytes();let original_identity=(source.as_ptr()as usize,source.len());let admitted=std::sync::atomic::AtomicUsize::new(0usize);let progress=std::cell::Cell::new(0usize);let parser_turn=std::sync::atomic::AtomicBool::new(false);let mut observe_progress=|_:NativeDecodeProgress|{progress.set(progress.get()+1);true};let mut allocate=|request:NativeDecodeAllocation|{assert_eq!(request.maximum_bytes,if parser_turn.load(std::sync::atomic::Ordering::SeqCst){limits.maximum_allocation_bytes.min(request.owned_bytes+g.maximum_capacity_bytes)}else{limits.maximum_allocation_bytes});assert!(request.bytes<=g.maximum_capacity_bytes);assert_eq!(request.owned_bytes,admitted.load(std::sync::atomic::Ordering::SeqCst));assert_eq!(request.next_owned_bytes,request.owned_bytes+request.bytes);assert!(request.next_owned_bytes<=limits.maximum_allocation_bytes);admitted.store(request.next_owned_bytes,std::sync::atomic::Ordering::SeqCst);Ok(())};let port:&mut NativeDecodeAllocationPort<'_>=&mut allocate;let mut retirement=NativeDecodeRetirementRecipient::new();let mut control=NativeDecodeControl::new_forwarded(limits.maximum_allocation_bytes,&mut observe_progress,port);control.install_retirement_recipient(&mut retirement).unwrap();
  for denied in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:1,..g}]{let(owner,born,released)=observe(||RetainedHistoryOriginJsonDecode::admit(source,(0,source.len()),limits,denied).unwrap());assert!(owner.is_none());assert_eq!((born,released),(0,0))}
  let(owner,born,released)=observe(||RetainedHistoryOriginJsonDecode::admit(source,(0,source.len()),limits,g).unwrap());assert_eq!((born,released),(0,0));let mut owner=owner.unwrap();receipt(&mut owner,g,born,released);assert_eq!(owner.source_identity(),original_identity);let changed=source.to_vec();assert!(owner.demands(&changed,&control,g.maximum_copy_bytes).is_err());let(mut births,mut releases)=(0,0);let mut ready=false;
  for _ in 0..cancelled{
   if owner.grammar_is_receivable(){let mut grammar=None;let(moved,born,released)=observe(||owner.take_grammar_into(&mut grammar,g).unwrap());assert!(moved);receipt(&mut owner,g,born,released);let(b,r)=close_box(grammar.take().unwrap(),&mut control,g);births+=b;releases+=r;continue}
   let demand=owner.demands(source,&control,g.maximum_copy_bytes).unwrap();for(axis,denied)in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:demand.depth.saturating_sub(1),..g},RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes.saturating_sub(1),..g},RetainedCloneGrant{maximum_release_bytes:demand.release_bytes.saturating_sub(1),..g},RetainedCloneGrant{maximum_copy_bytes:demand.copy_bytes.saturating_sub(1),..g}].into_iter().enumerate(){if axis==2&&demand.capacity_bytes==0||axis==3&&demand.release_bytes==0||axis==4&&demand.copy_bytes==0{continue}let original_admitted=admitted.load(std::sync::atomic::Ordering::SeqCst);let(result,born,released)=observe(||owner.step(source,&mut control,denied).unwrap());assert_eq!(result,RetainedHistoryOriginJsonStep::Blocked);assert_eq!((born,released),(0,0));assert_eq!(admitted.load(std::sync::atomic::Ordering::SeqCst),original_admitted);assert!(owner.receipt().is_none())}
   parser_turn.store(owner.grammar.is_some()&&!owner.grammar_complete,std::sync::atomic::Ordering::SeqCst);let(result,born,released)=observe(||owner.step(source,&mut control,g).unwrap());parser_turn.store(false,std::sync::atomic::Ordering::SeqCst);births+=born;releases+=released;if owner.receipt().is_some(){receipt(&mut owner,g,born,released)}else{assert_eq!((born,released),(0,0))}assert_eq!(owner.source_identity(),original_identity);if result==RetainedHistoryOriginJsonStep::Ready{ready=true;break}assert_eq!(result,RetainedHistoryOriginJsonStep::Progress)
  }
  if cancelled==100000{assert!(ready);let mut output=None;let(moved,born,released)=observe(||owner.take_ready_into(&mut output,g).unwrap());assert!(moved);receipt(&mut owner,g,born,released);match output.take().unwrap(){MutationOrigin::Owner=>assert_eq!(row["kind"],"owner"),MutationOrigin::Contributed{plugin_id,mutation_id,payload_hash:_}=>{assert_eq!(row["kind"],"contributed");for text in[plugin_id,mutation_id.0]{let(b,r)=close_box(text,&mut control,g);births+=b;releases+=r}},MutationOrigin::Transaction{initiator}=>{assert_eq!(row["kind"],"transaction");for text in[Some(initiator.artifact_id),Some(initiator.artifact_kind),initiator.dialect].into_iter().flatten(){let(b,r)=close_box(text,&mut control,g);births+=b;releases+=r}}}}
  else{
   owner.cancel();let mut grammar=None;let(moved,born,released)=observe(||owner.take_grammar_into(&mut grammar,g).unwrap());if moved{receipt(&mut owner,g,born,released);let(b,r)=close_box(grammar.take().unwrap(),&mut control,g);births+=b;releases+=r}else{assert_eq!((born,released),(0,0))}
   let mut value=None;let(moved,born,released)=observe(||owner.take_partial_value_into(&mut value,g).unwrap());if moved{receipt(&mut owner,g,born,released);let(b,r)=close_box(value.take().unwrap(),&mut control,g);births+=b;releases+=r}else{assert_eq!((born,released),(0,0))}
   let mut projection=None;let(moved,born,released)=observe(||owner.take_projection_into(&mut projection,g).unwrap());if moved{receipt(&mut owner,g,born,released);let p=projection.as_mut().unwrap();let mut partial=None;let(moved,born,released)=observe(||p.take_partial_into(&mut partial,g).unwrap());assert!(moved);let(issued,received)=p.take_receipt().unwrap();assert_eq!(issued,g);assert_eq!((born,released),(received.retained_capacity_bytes,received.released_bytes));for _ in 0..100000{let part=partial.as_mut().unwrap();if part.terminal_is_empty(){break}let demand=part.close_demands(g.maximum_copy_bytes).unwrap();control.charge(demand.capacity_bytes).unwrap();let(p,born,released)=observe(||part.close_step(g).unwrap());assert_eq!((born,released),(p.retained_capacity_bytes,p.released_bytes));births+=born;releases+=released}assert!(partial.as_ref().unwrap().terminal_is_empty());drop(partial);p.close_step(g).unwrap();p.take_receipt();assert!(p.terminal_is_empty());drop(projection)}else{assert_eq!((born,released),(0,0))}
  }
  for _ in 0..16{if owner.terminal_is_empty(){break}let(result,born,released)=observe(||owner.close_step(g).unwrap());assert_ne!(result,RetainedHistoryOriginJsonStep::Blocked);receipt(&mut owner,g,born,released);births+=born;releases+=released}assert!(owner.terminal_is_empty());assert_eq!(births,releases);assert_eq!(control.owned_bytes(),admitted.load(std::sync::atomic::Ordering::SeqCst));assert!(!control.has_retirement_owner());let(_,born,released)=observe(||drop(owner));assert_eq!((born,released),(0,0));drop(control);assert!(retirement.terminal_is_empty());
 }}
 eprintln!("[DEBUG] Original History origin JSON reads unchanged per-turn byte source through original forwarded capacity port, fixed complete limits and full5 grants; actual grammar/Dsl/error/typed recipient custody survives paid handoffs, physical heap balances and terminalDrop0");
}
